function ensureMusic(){if(typeof Audio==='undefined')return null;backgroundMusic=backgroundMusic||new Audio('MainTheme.mp3');backgroundMusic.loop=true;backgroundMusic.preload='auto';syncAudioLevels();if(!masterMuted&&musicVolume>0)backgroundMusic.play().catch(()=>{});return backgroundMusic}
function syncAudioLevels(){if(backgroundMusic){backgroundMusic.volume=masterMuted?0:musicVolume*.6;if(masterMuted||musicVolume<=0)backgroundMusic.pause()}}
function setSfxVolume(value){sfxVolume=clamp(Number(value)||0,0,1);localStorage.setItem(SFX_VOLUME_KEY,String(sfxVolume));if(!masterMuted&&sfxVolume>0)ensureAudio()}
function setMusicVolume(value){musicVolume=clamp(Number(value)||0,0,1);localStorage.setItem(MUSIC_VOLUME_KEY,String(musicVolume));syncAudioLevels();if(!masterMuted&&musicVolume>0)ensureMusic()}
function setMasterMute(value){masterMuted=!!value;localStorage.setItem(MASTER_MUTE_KEY,masterMuted?'1':'0');syncAudioLevels();if(!masterMuted){ensureMusic();playSfx('ui')}}
function ensureAudio(){if(masterMuted)return null;const AudioCtor=globalThis.AudioContext||globalThis.webkitAudioContext;if(!AudioCtor)return null;audioContext=audioContext||new AudioCtor();if(audioContext.state==='suspended')audioContext.resume();return audioContext}
function soundTone(ctx,out,frequency,start,duration,type='square',gain=.18,endFrequency=frequency){const osc=ctx.createOscillator(),amp=ctx.createGain();osc.type=type;osc.frequency.setValueAtTime(Math.max(30,frequency),start);osc.frequency.exponentialRampToValueAtTime(Math.max(30,endFrequency),start+duration);amp.gain.setValueAtTime(.0001,start);amp.gain.exponentialRampToValueAtTime(Math.max(.0001,gain),start+.008);amp.gain.exponentialRampToValueAtTime(.0001,start+duration);osc.connect(amp).connect(out);osc.start(start);osc.stop(start+duration+.02)}
function soundNoise(ctx,out,start,duration,gain=.12){const frames=Math.max(1,Math.floor(ctx.sampleRate*duration)),buffer=ctx.createBuffer(1,frames,ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<frames;i++)data[i]=(Math.random()*2-1)*(1-i/frames);const src=ctx.createBufferSource(),amp=ctx.createGain();src.buffer=buffer;amp.gain.setValueAtTime(gain,start);amp.gain.exponentialRampToValueAtTime(.0001,start+duration);src.connect(amp).connect(out);src.start(start)}
function playSfx(name){if(sfxVolume<=0)return;const ctx=ensureAudio();if(!ctx)return;const now=ctx.currentTime+.005,out=ctx.createGain();out.gain.value=sfxVolume*.45;out.connect(ctx.destination);if(name==='ui')soundTone(ctx,out,520,now,.045,'square',.06,660);else if(name==='blade'){soundNoise(ctx,out,now,.11,.18);soundTone(ctx,out,900,now,.1,'sawtooth',.1,240)}else if(name==='heavy'){soundTone(ctx,out,105,now,.18,'square',.28,48);soundNoise(ctx,out,now,.13,.25)}else if(name==='bow'){soundTone(ctx,out,720,now,.12,'triangle',.13,180);soundTone(ctx,out,150,now+.1,.08,'square',.1,70)}else if(name==='fire'){soundNoise(ctx,out,now,.28,.14);soundTone(ctx,out,180,now,.25,'sawtooth',.15,520)}else if(name==='frost'){[880,1175,1320].forEach((f,i)=>soundTone(ctx,out,f,now+i*.035,.18,'sine',.09,f*.72))}else if(name==='lightning'){soundNoise(ctx,out,now,.18,.28);soundTone(ctx,out,1450,now,.12,'square',.12,180)}else if(name==='holy'||name==='heal'){[440,554,659].forEach((f,i)=>soundTone(ctx,out,f,now+i*.07,.28,'sine',.11,f*1.08))}else if(name==='status'){soundTone(ctx,out,310,now,.2,'triangle',.13,155)}else if(name==='crit'){soundTone(ctx,out,980,now,.09,'square',.2,1960);soundNoise(ctx,out,now,.08,.2)}else if(name==='death'){soundTone(ctx,out,220,now,.4,'sawtooth',.18,55)}else if(name==='victory'){[392,523,659,784].forEach((f,i)=>soundTone(ctx,out,f,now+i*.1,.28,'square',.1,f))}else if(name==='defeat'){[294,247,196,147].forEach((f,i)=>soundTone(ctx,out,f,now+i*.14,.3,'triangle',.12,f*.8))}else{soundTone(ctx,out,150,now,.12,'square',.15,75);soundNoise(ctx,out,now,.09,.12)}}
function heroAttackSfx(h,action){if(action!=='basic')return h.class==='Mage'?(action==='primary'?'fire':'frost'):h.class==='Paladin'?'holy':h.class==='Priest'?'heal':h.class==='Ranger'?'bow':'heavy';const p=weaponStatusProfile(h.gear?.Weapon),name=(h.gear?.Weapon?.weaponTemplate||'').toLowerCase();if(p&&['burning','frostbite','shocked','radiant','cursed','poisoned'].includes(p.key))return p.key==='frostbite'?'frost':p.key==='shocked'?'lightning':p.key==='radiant'?'holy':p.key==='burning'?'fire':'status';if(/bow|crossbow/.test(name))return'bow';if(/mace|hammer|staff|axe|halberd/.test(name))return'heavy';return'blade'}
