function attributeSkillNodes(){const cx=1200,cy=1200,layers=[1,2,3,4,4,4],starts=[0,1,3,6,10,14];return Object.entries(ATTRIBUTE_SKILL_PATHS).flatMap(([path,data])=>Array.from({length:18},(_,index)=>{const layer=starts.findLastIndex(start=>index>=start),count=layers[layer],slot=index-starts[layer],lane=count===1?0:(slot/(count-1)-.5),angle=(data.angle+lane*(22+layer*7))*Math.PI/180,radius=145+layer*175,[name,desc,effect]=TRUNK_SKILLS[path][index%TRUNK_SKILLS[path].length],previousCount=layer?layers[layer-1]:0,parentSlot=layer?Math.round(slot*Math.max(0,previousCount-1)/Math.max(1,count-1)):null,parent=layer?starts[layer-1]+parentSlot:null;return{id:`attribute-${path}-${index}`,name,desc,effect,path,depth:layer,maxRank:1,major:false,basic:true,color:data.color,x:cx+Math.cos(angle)*radius,y:cy+Math.sin(angle)*radius,requires:parent==null?null:`attribute-${path}-${parent}`}}))}
