function classSkillNodes(className){
const bridgeEntrances={'weapon-dagger-0':'bridge-str-dex-3','weapon-arcane-0':'bridge-dex-int-3','weapon-sword-0':'bridge-int-str-3'},oldBridgeTargets=new Set(['cluster-precision-0','cluster-mana-0','cluster-armor-0']),localLinks={'cluster-armor-1':'cluster-vitality-2','cluster-blood-1':'cluster-armor-2','cluster-tempo-1':'cluster-precision-2','cluster-affliction-1':'cluster-tempo-2','cluster-ward-1':'cluster-mana-2','cluster-restoration-1':'cluster-ward-2'},universal=[...attributeSkillNodes(),...ringSkillNodes(),...specializationSkillNodes(),...outerSkillNodes()].filter(node=>!node.id.endsWith('-ring-gateway')).map(node=>{const match=node.id.match(/^(str|dex|int)-ring-(0|3)$/);if(match)return{...node,requires:match[2]==='0'?`attribute-${match[1]}-6`:`${match[1]}-ring-0`};if(oldBridgeTargets.has(node.id))return{...node,requiresAny:null};if(bridgeEntrances[node.id])return{...node,requiresAny:[node.requires,bridgeEntrances[node.id]]};return node}),cx=1200,cy=1200,layoutCenter=4000;
 const anchors=['attribute-str-14','attribute-str-15','attribute-str-16','attribute-str-17','attribute-dex-14','attribute-dex-15','attribute-dex-16','attribute-dex-17','attribute-int-14','attribute-int-15','attribute-int-16','int-ring-6'];
 const specific=(SKILL_PATHS[className]||[]).flatMap((path,pathIndex)=>path.map(([name,desc,effect],depth)=>{const index=pathIndex*3+depth,anchor=anchors[index],origin=universal.find(node=>node.id===anchor),dx=origin.x-cx,dy=origin.y-cy,length=Math.hypot(dx,dy)||1,distance=depth===2?360:300,x=origin.x+dx/length*distance,y=origin.y+dy/length*distance,id=`${className.toLowerCase()}-${pathIndex}-${depth}`;return{id,layoutId:`class-${pathIndex}-${depth}`,name,desc,effect,path:`class-${pathIndex}`,depth,maxRank:1,major:depth===2,classSpecific:true,x,y,requires:anchor}}));
 const corrections={};
 return[...universal,...specific].map(node=>{const layoutId=node.layoutId||node.id,position=SKILL_LAYOUT_POSITIONS[layoutId],correction=corrections[layoutId];return{...node,...correction,layoutId,x:position?.x??correction?.x??layoutCenter+(node.x-cx)*1.72,y:position?.y??correction?.y??layoutCenter+(node.y-cy)*1.72}})
}
async function loadSkillTreeLayout(){try{const response=await fetch(SKILL_LAYOUT_URL,{cache:'no-store'});if(!response.ok)throw new Error(`HTTP ${response.status}`);const xml=new DOMParser().parseFromString(await response.text(),'image/svg+xml');const positions={};xml.querySelectorAll('[data-layout-id]').forEach(element=>{const transform=element.getAttribute('transform')||'',match=transform.match(/translate\(\s*(-?[\d.]+)[ ,]+(-?[\d.]+)\s*\)/),x=Number(match?.[1]??element.getAttribute('data-x')),y=Number(match?.[2]??element.getAttribute('data-y'));if(Number.isFinite(x)&&Number.isFinite(y))positions[element.getAttribute('data-layout-id')]={x,y}});if(Object.keys(positions).length)SKILL_LAYOUT_POSITIONS=positions}catch(error){console.warn('Shared skill-tree SVG layout could not be loaded; using built-in positions.',error)}}
function skillRank(h,id){return Math.min(1,h?.skillRanks?.[id]||0)}
function skillBonus(h,key){const nodes=classSkillNodes(h?.class),total=nodes.reduce((sum,node)=>sum+(node.effect?.[key]||0)*skillRank(h,node.id),0);return key==='dotDamage'&&nodes.some(node=>node.effect?.dotPact&&skillRank(h,node.id))?total+.6:total}
function heroWeaponFamily(h){const name=(h?.gear?.Weapon?.weaponTemplate||h?.gear?.Weapon?.name||'').toLowerCase();if(/dagger|knife|dirk|kris/.test(name))return'Dagger';if(/sword|blade/.test(name))return'Sword';if(/axe/.test(name))return'Axe';if(/hammer|mace/.test(name))return'Hammer';if(/bow|crossbow/.test(name))return'Bow';if(/spear|halberd/.test(name))return'Spear';if(/staff|wand|orb|spellbook|scepter/.test(name))return'Arcane';return null}
function weaponSkillBonus(h,key){const family=heroWeaponFamily(h);return family?skillBonus(h,`weapon${family}${key}`):0}
function adjustedDotTurns(h,turns){return Math.max(1,Math.ceil((turns+skillBonus(h,'dotDuration'))*(skillBonus(h,'compressedDots')?.5:1)))}
function dotPower(h){return 1+skillBonus(h,'dotDamage')+weaponSkillBonus(h,'Dot')+(skillBonus(h,'compressedDots')?.5:0)}
function spreadEnemyStatus(h,target,key,status){target.statuses=target.statuses||{};target.statuses[key]={...status};if(!skillBonus(h,'statusSpread'))return;livingEnemies().filter(enemy=>enemy.id!==target.id).forEach(enemy=>{enemy.statuses=enemy.statuses||{};enemy.statuses[key]={...status}})}
function spentSkillPoints(h){return classSkillNodes(h?.class).reduce((sum,node)=>sum+skillRank(h,node.id),0)}
function availableSkillPoints(h){return Math.max(0,(h?.level||1)-1-spentSkillPoints(h))}
