function heroArmorProficiency(h){return chosenSubclass(h)?.armorOverride||CLASSES[h.class]?.armor}
function partyPreferredArmorClasses(){return new Set((state.run?.heroes||[]).map(heroArmorProficiency).filter(Boolean))}
function partyCanEquip(item){const heroes=state.run?.heroes||[];return!heroes.length||heroes.some(h=>canEquip(h,item))}
function scalableWeaponRecipes(tier){if(tier<4)return[];return Object.entries(ITEM_DATA.weapons).filter(([,weapon])=>weapon?.image).map(([template])=>[`Runesteel ${template}`,'Weapon',template,null,tier,{}])}
function makeCanonicalItem(forcedRarity=null){const tier=equipmentTierForRun(),catalogTier=Math.min(tier,Math.max(1,...RECIPE_DATA.filter(r=>r[1]!=='Material'&&r[1]!=='Rune').map(r=>r[4]||1))),available=[...RECIPE_DATA.filter(r=>r[4]===catalogTier&&r[1]!=='Material'&&r[1]!=='Rune'),...scalableWeaponRecipes(tier)].sort(()=>Math.random()-.5);for(const recipe of available){const scaledRecipe=[...recipe];scaledRecipe[4]=tier;const item=makeRecipeItem(scaledRecipe,forcedRarity||rollRarity(tier));if(partyCanEquip(item))return item}for(let attempt=0;attempt<30;attempt++){const item=makeItem();if(partyCanEquip(item))return item}const fallback=makeItem();fallback.slot='Accessory';delete fallback.allowedClasses;return fallback}
function rollShopRarity(guaranteed=false){const r=Math.random(),result=guaranteed?(r<.04?'Mythic':r<.22?'Legendary':'Epic'):r<.012?'Mythic':r<.07?'Legendary':r<.30?'Epic':r<.62?'Rare':r<.88?'Uncommon':'Common';return gateHighRarity(result)}
function shopItemCost(item){const rarityCost={Common:32,Uncommon:48,Rare:72,Epic:110,Legendary:165,Mythic:240}[item.rarity]||32,tier=item.tier||1,normalTier=Math.min(4,tier),endlessTiers=Math.max(0,tier-4);return Math.round(rarityCost*Math.pow(normalTier,1.15)*Math.pow(1.25,endlessTiers))}
function randomUnownedRelic(){return pick(RELICS.filter(x=>!(state.run.relics||[]).includes(x[0])))}
function makeRewards(){return[{kind:'item',item:makeCanonicalItem()},{kind:'gold',amount:35+state.run.region*30},{kind:'perk',perk:pick(PERKS)}]}
function makeEliteRelicRewards(){const unowned=RELICS.filter(x=>x[3]==='elite'&&!(state.run.relics||[]).includes(x[0])),pool=unowned.length>=3?unowned:unowned.concat(RELICS.filter(x=>x[3]!=='elite'&&!(state.run.relics||[]).includes(x[0])));return pool.sort(()=>Math.random()-.5).slice(0,3).map(relic=>({kind:'relic',relic}))}
function applyRunRelicsToHero(h){if(h.manaRegenVersion!==4){h.manaRegen=ABILITIES[h.class].regen+trainingRank('manaRegen')*.2;h.manaRegenVersion=4}if(hasRelic('sealedReservoir')&&!h.sealedReservoirApplied){h.maxMana=Math.round(h.maxMana*1.6);h.mana=Math.round(h.mana*1.6);h.sealedReservoirApplied=true}if(hasRelic('glassHeart')&&!h.glassHeartApplied){h.maxHp=Math.max(1,Math.round(h.maxHp*.7));h.hp=Math.min(h.maxHp,Math.max(1,Math.round(h.hp*.7)));h.glassHeartApplied=true}return h}
function activateRelic(id){state.run.relics=state.run.relics||[];if(!state.run.relics.includes(id))state.run.relics.push(id);state.run.heroes.forEach(applyRunRelicsToHero)}
function itemFolder(slot){return slot==='Weapon'?'weapons':slot==='Armor'?'armor':'accessories'}
function itemSlug(name){return String(name||'default').toLowerCase().replace(/['’]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function itemArt(it){const src=it.image?`../guildmaster/${it.image}`:`${ASSET}items/${itemFolder(it.slot)}/${itemSlug(it.name)}.png`;return `<span class="itemIcon"><img src="${src}" alt="" onerror="this.style.display='none';this.nextElementSibling.style.display='grid'"><span class="itemFallback">${it.slot==='Weapon'?'⚔':it.slot==='Armor'?'▣':'◇'}</span></span>`}
function rewardChoiceHtml(x,i){if(x.kind==='item')return `<button class="choice rewardChoice" onclick="takeReward(${i})">${itemArt(x.item)}<strong class="rarity-${x.item.rarity}">${x.item.name}</strong><div class="rewardType">Tier ${x.item.tier} · ${x.item.rarity} ${x.item.slot}</div><div class="itemStats">${itemStatLines(x.item).map(s=>`<span>${s}</span>`).join('')}</div><span class="choiceHint">Add to inventory →</span></button>`;if(x.kind==='gold')return `<button class="choice rewardChoice" onclick="takeReward(${i})"><span class="big">◉</span><strong>${x.amount} Run Gold</strong><div class="muted">Spend it now or risk carrying it home.</div><span class="choiceHint">Take reward →</span></button>`;if(x.kind==='relic')return `<button class="choice rewardChoice relicReward ${x.relic[3]==='elite'?'relicElite':'relicStandard'}" onclick="takeReward(${i})"><span class="big">⬡</span><strong>${x.relic[1]}</strong><div class="muted">${x.relic[2]}</div><span class="choiceHint">Claim relic →</span></button>`;return `<button class="choice rewardChoice" onclick="takeReward(${i})"><span class="big">◆</span><strong>${x.perk[0]}</strong><div class="muted">${x.perk[1]} for this run.</div><span class="choiceHint">Take boon →</span></button>`}
function renderReward(){const r=state.run,relicStage=r.pendingReward.every(x=>x.kind==='relic');return `<section class="panel rewardsPanel"><div class="screenTitle"><div class="eyebrow">${relicStage?'RELIC SPOILS':'VICTORY SPOILS'}</div><h2>${relicStage?'Choose a Relic—or Leave Them':'Choose One Reward'}</h2><p class="muted">${relicStage?'These powerful relics are optional.':'Choose equipment, gold, or a run boon first.'}</p></div><div class="choiceGrid">${r.pendingReward.map(rewardChoiceHtml).join('')}</div>${relicStage?'<div class="actions"><button class="btn" onclick="declineEliteRelic()">Take No Relic</button></div>':''}</section>`}
function declineEliteRelic(){const r=state.run;if(!r?.pendingReward?.every(x=>x.kind==='relic'))return;r.pendingReward=null;delete r.pendingEliteRelics;advanceNode()}
function takeReward(i){const r=state.run,x=r.pendingReward[i],relicStage=x.kind==='relic';if(x.kind==='item'){r.inventory=r.inventory||[];r.inventory.push(x.item);toast(`${x.item.name} added to the run inventory.`)}else if(x.kind==='gold')r.gold+=x.amount;else if(x.kind==='relic'){activateRelic(x.relic[0]);toast(`${x.relic[1]} joined the party relics.`)}else if(x.kind==='perk'){r.perks.push({name:x.perk[0],desc:x.perk[1],type:x.perk[2],value:x.perk[3]});if(x.perk[2]==='hp')r.heroes.forEach(h=>{const gain=Math.round(h.maxHp*x.perk[3]);h.maxHp+=gain;h.hp+=gain})}if(!relicStage&&r.pendingEliteRelics?.length){r.pendingReward=r.pendingEliteRelics;delete r.pendingEliteRelics;save();render();return}r.pendingReward=null;delete r.pendingEliteRelics;advanceNode()}
function canEquip(h,item){return!!h&&!!item&&['Weapon','Armor','Accessory'].includes(item.slot)}
function statComparison(item,old){const next=itemStats(item),prev=itemStats(old),lines=[];if(item.weaponPower||old?.weaponPower){const d=(item.weaponPower||0)-(old?.weaponPower||old?.power||0);if(d)lines.push(`<b class="${d>0?'gain':'loss'}">${d>0?'+':''}${d} Attack</b>`)}ITEM_STAT_KEYS.forEach(k=>{const d=(next[k]||0)-(prev[k]||0);if(!d)return;lines.push(`<b class="${d>0?'gain':'loss'}">${d>0?'+':''}${PERCENT_STATS.has(k)?Math.round(d*100)+'%':d} ${STAT_LABELS[k]}</b>`)});return lines.join('')||'<span class="muted">No stat change</span>'}
function equipInventoryItem(itemId,heroId){const item=state.run.inventory.find(x=>x.id===itemId),hero=state.run.heroes.find(h=>h.id===heroId);if(!item||!hero||!canEquip(hero,item))return;const previousOwner=equippedOwner(item);if(previousOwner)Object.keys(previousOwner.gear).forEach(slot=>{if(previousOwner.gear[slot]?.id===item.id)previousOwner.gear[slot]=null});const oldNatural=naturalMaxHp(hero),oldStats=gearStats(hero),hpRatio=hero.hp/hero.maxHp,manaRatio=hero.maxMana?hero.mana/hero.maxMana:1;hero.gear[item.slot]=item;const nextStats=gearStats(hero);hero.maxHp=Math.max(1,hero.maxHp+naturalMaxHp(hero)-oldNatural);hero.hp=Math.max(1,hero.maxHp*hpRatio);hero.maxMana=Math.max(0,hero.maxMana+nextStats.mana-oldStats.mana);hero.mana=hero.maxMana*manaRatio;closeOverlay();save();toast(`${hero.name} equipped ${item.name}.`);render()}
function equipBest(item){state.run.inventory=state.run.inventory||[];state.run.inventory.push(item);toast(`${item.name} added to the run inventory.`)}
function advanceNode(){const r=state.run;delete r.lockedNodeType;r.step++;r.mode='map';save();render()}
function renderRecruit(){const r=state.run;if(r.endless&&loneWolfActive(r)){r.region++;r.step=0;r.nodes=makeRegionMap();r.mode='map';delete r.recruitChoices;delete r.modifierChoices;delete r.lockedNodeType;save();return renderMap()}const count=r.rerolls?.recruit||0,next=REGIONS[(r.region+1)%REGIONS.length];return `<section class="panel"><div class="screenTitle"><h2>A Survivor Joins the Road</h2><p class="muted">Inspect the candidates and recruit one before entering ${next.name}.</p>${count?`<button class="btn rerollButton" onclick="rerollRecruitment()">↻ Reroll All Candidates · ${count} left</button>`:''}</div><div class="heroGrid">${r.recruitChoices.map((h,i)=>`<div class="choice recruitChoice">${heroCard(h)}<button class="btn gold" onclick="takeRecruit(${i})">Recruit ${h.class}</button></div>`).join('')}</div></section>`}
function takeRecruit(i){const r=state.run;if(r.endless&&loneWolfActive(r))return advanceEndlessRegion();const h=r.recruitChoices[i],hpBonus=r.perks.filter(p=>p.type==='hp').reduce((a,p)=>a+p.value,0);if(hpBonus){h.maxHp=Math.round(h.maxHp*(1+hpBonus));h.hp=h.maxHp}if(r.endless){r.heroes.push(h);applyRunRelicsToHero(h);return advanceEndlessRegion()}r.heroes.push(h);applyRunRelicsToHero(h);r.region++;r.step=0;r.nodes=makeRegionMap();r.mode='map';delete r.recruitChoices;delete r.lockedNodeType;if(!hasRelic('crimsonCovenant'))r.heroes.forEach(hero=>hero.hp=Math.max(1,Math.min(hero.maxHp,hero.hp+hero.maxHp*.35)));save();render()}
function abilityShrine(){const heroes=state.run.heroes.filter(h=>h.hp>0&&(h.augments||[]).length<3);if(!heroes.length){toast('The shrine has nothing left to teach this party.');return advanceNode()}showOverlay('Shrine of Mastery',`<p class="muted">Choose an adventurer whose class ability will be transformed for this run.</p><div class="equipGrid">${heroes.map(h=>`<button class="choice equipChoice" onclick="chooseAbilityAugment(${h.id})">${img('classes/'+CLASSES[h.class].icon)}<strong>${h.name}</strong><div class="muted">${h.class} · ${ABILITIES[h.class].name}</div><div class="itemStats">${(h.augments||[]).map(id=>`<span>${ABILITY_AUGMENTS[h.class].find(x=>x[0]===id)?.[1]||id}</span>`).join('')||'<span>No augments yet</span>'}</div></button>`).join('')}</div>`)}
function chooseAbilityAugment(heroId){const h=findHero(heroId),choices=ABILITY_AUGMENTS[h.class].filter(x=>!h.augments.includes(x[0]));if(!choices.length)return;closeOverlay();showOverlay('Empower '+ABILITIES[h.class].name,`<p class="muted">Choose one permanent ability change for ${h.name} this run.</p><div class="choiceGrid">${choices.map(a=>`<button class="choice" onclick="takeAbilityAugment(${h.id},'${a[0]}')"><strong>${a[1]}</strong><div class="muted">${a[2]}</div></button>`).join('')}</div>`)}
function takeAbilityAugment(heroId,id){const h=findHero(heroId),def=ABILITY_AUGMENTS[h.class].find(x=>x[0]===id);if(!def||h.augments.includes(id))return;h.augments.push(id);closeOverlay();toast(`${h.name} learned ${def[1]}.`);advanceNode()}
function relicVault(){state.run.relics=state.run.relics||[];const choices=RELICS.filter(x=>x[3]!=='elite'&&!state.run.relics.includes(x[0])).sort(()=>Math.random()-.5).slice(0,3);if(!choices.length){toast('The relic vault is empty.');return advanceNode()}showOverlay('Relic Vault',`<p class="muted">Choose one relic, or leave if none fit your build.</p><div class="choiceGrid">${choices.map(r=>`<button class="choice relicStandard" onclick="takeRelic('${r[0]}')"><span class="big">⬡</span><strong>${r[1]}</strong><div class="muted">${r[2]}</div></button>`).join('')}</div><div class="actions"><button class="btn" onclick="declineVaultRelic()">Take No Relic</button></div>`)}
function declineVaultRelic(){closeOverlay();advanceNode()}
function takeRelic(id){const relic=RELICS.find(x=>x[0]===id);if(!relic||state.run.relics.includes(id))return;activateRelic(id);closeOverlay();toast(`${relic[1]} joined the party relics.`);advanceNode()}
function treasureEvent(){const item=makeCanonicalItem(),gold=30+state.run.region*25;showOverlay('An Abandoned Cache',`<p class="muted">The party can only carry one prize safely.</p><div class="choiceGrid"><button class="choice" onclick="eventItem(${JSON.stringify(item).replace(/"/g,'&quot;')})"><strong>${item.name}</strong><div class="muted">Tier ${item.tier} · ${item.rarity} ${item.slot}</div></button><button class="choice" onclick="eventGold(${gold})"><strong>${gold} Gold</strong><div class="muted">Add it to the run purse.</div></button></div>`)}
function eventItem(item){equipBest(item);closeOverlay();advanceNode()}function eventGold(n){state.run.gold+=n;closeOverlay();advanceNode()}
function storyEvent(){const h=pick(state.run.heroes),events=[{title:'A Broken Oath',text:`${h.name} finds the banner of a failed expedition.`,choices:[['Honor the fallen','Party gains 10% maximum HP','oathHp'],['Strip it for valuables','Gain 55 Run Gold','gold55']]},{title:'The Narrow Bridge',text:'Something follows beneath the bridge.',choices:[['Cross carefully','Heal the most wounded hero','healWounded'],['Set an ambush','Gain 12% party attack','ambush']]},{title:'A Familiar Voice',text:`${h.name} hears someone calling from the dark.`,choices:[['Follow the voice','Gain a usable random item','randomGear'],['Keep moving','Gain 40 Run Gold','gold40']]}],e=pick(events);showOverlay(e.title,`<p>${e.text}</p><div class="choiceGrid">${e.choices.map(([name,desc,effect])=>`<button class="choice" onclick="resolveStory('${effect}')"><strong>${name}</strong><div class="muted">${desc}</div></button>`).join('')}</div>`)}
function resolveStory(effect){const r=state.run;if(effect==='oathHp'){r.perks.push({name:'Oathbound',desc:'Party maximum HP +10%.',type:'hp',value:.1});r.heroes.forEach(h=>{h.maxHp=Math.round(h.maxHp*1.1);if(!hasRelic('crimsonCovenant'))h.hp=Math.min(h.maxHp,h.hp+h.maxHp*.2)})}else if(effect==='gold55')r.gold+=55;else if(effect==='healWounded'){const h=[...r.heroes].sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];if(hasRelic('crimsonCovenant'))toast('The Crimson Covenant rejects the healing.');else{h.hp=Math.min(h.maxHp,h.hp+h.maxHp*.5);toast(`${h.name} recovered 50% health.`)}}else if(effect==='ambush')r.perks.push({name:'Ambush Training',desc:'Party attack +12%.',type:'attack',value:.12});else if(effect==='randomGear'){const item=makeCanonicalItem();r.inventory=r.inventory||[];r.inventory.push(item);toast(`${item.name} added to the run inventory.`)}else if(effect==='gold40')r.gold+=40;closeOverlay();advanceNode()}
function merchantEvent(){const r=state.run,priceMult=Math.pow(2,endlessModifierCount('inflation'));if(!r.merchantStock){const gear=Array.from({length:6},(_,index)=>{const item=makeCanonicalItem(rollShopRarity(index===0)),cost=Math.round(shopItemCost(item)*priceMult);return{kind:'gear',item,cost}}),consumables=Object.entries(CONSUMABLES).map(([id,c])=>({kind:'consumable',id,cost:Math.round((c.cost+r.region*6)*priceMult)}));r.merchantStock=[...gear,...consumables]}showOverlay('The Road Trader',`<p class="muted">Every trader carries at least one Epic-or-better item. Prices rise with rarity and tier.${priceMult>1?` Endless inflation is ×${priceMult}.`:''}</p><p class="muted">Buy as many items as you can afford. The trader leaves only when you choose Leave.</p><div class="choiceGrid traderStock">${r.merchantStock.map((stock,index)=>stock.kind==='gear'?`<button class="choice traderItem" ${r.gold<stock.cost?'disabled':''} onclick="buyMerchantStock(${index})"><span class="traderPrice">${stock.cost}g</span>${itemArt(stock.item)}<strong class="rarity-${stock.item.rarity}">${stock.item.name}</strong><div class="muted">Tier ${stock.item.tier} · ${stock.item.rarity}</div><div class="itemStats">${itemStatLines(stock.item).map(s=>`<span>${s}</span>`).join('')}</div><span class="choiceHint">Buy equipment →</span></button>`:`<button class="choice traderItem consumableShopItem" ${r.gold<stock.cost?'disabled':''} onclick="buyMerchantStock(${index})"><span class="traderPrice">${stock.cost}g</span><span class="consumableIcon">${CONSUMABLES[stock.id].icon}</span><strong>${CONSUMABLES[stock.id].name}</strong><div class="muted">${CONSUMABLES[stock.id].desc}</div><span class="choiceHint">Buy consumable →</span></button>`).join('')}</div><div class="actions"><button class="btn primary" onclick="leaveMerchant()">Leave Trader</button></div>`)}
function buyMerchantStock(index){const r=state.run,stock=r.merchantStock?.[index];if(!stock||r.gold<stock.cost)return;r.gold-=stock.cost;if(stock.kind==='gear'){r.inventory=r.inventory||[];r.inventory.push(stock.item);toast(`${stock.item.name} added to inventory.`)}else{r.consumables=r.consumables||{};r.consumables[stock.id]=(r.consumables[stock.id]||0)+1;toast(`${CONSUMABLES[stock.id].name} added to inventory.`)}r.merchantStock.splice(index,1);save();merchantEvent()}
function leaveMerchant(){delete state.run.merchantStock;closeOverlay();advanceNode()}
function rerollOverlayControl(title){const type=title==='Relic Vault'?'vault':title==='The Road Trader'?'shop':title.startsWith('Empower ')?'shrine':null,count=type?(state.run?.rerolls?.[type]||0):0;return type&&count?`<div class="rerollBar"><button class="btn rerollButton" onclick="useRunReroll('${type}')">↻ Reroll ${type==='shop'?'Trader Stock':type==='vault'?'Relic Vault':'Shrine Choices'} · ${count} left</button></div>`:''}
function showOverlay(title,body){const current=$('#overlay'),preserveDraft=current?.querySelector('h2')?.textContent.startsWith('Choose Party Slot')&&body.includes('characterInspect');if(current){if(preserveDraft){current.removeAttribute('id');current.classList.add('overlayUnder')}else current.remove()}document.body.insertAdjacentHTML('beforeend',`<div class="overlay" id="overlay" onclick="if(event.target===this)closeOverlay()"><section class="panel modal"><button class="modalClose" onclick="closeOverlay()" aria-label="Close window" title="Close">×</button><h2>${title}</h2>${body}${rerollOverlayControl(title)}</section></div>`);const tree=$('.skillTreeViewport');if(tree){const svg=tree.querySelector('.skillLines');if(svg)svg.setAttribute('viewBox','0 0 4400 4400');tree.scrollLeft=Math.max(0,2000-tree.clientWidth/2);tree.scrollTop=Math.max(0,2000-tree.clientHeight/2);enableSkillTreePan(tree)}}function closeOverlay(){const current=$('#overlay');if(!current)return;current.remove();const previous=[...document.querySelectorAll('.overlayUnder')].pop();if(previous){previous.classList.remove('overlayUnder');previous.id='overlay'}}
function enableSkillTreePan(viewport){let dragging=false,startX=0,startY=0,startLeft=0,startTop=0,moved=false,zoom=1;const canvas=viewport.querySelector('.skillTree');viewport.title='Drag to move · Mouse wheel to zoom';viewport.onpointerdown=event=>{if(event.button!==0||event.target.closest('.skillNode'))return;dragging=true;moved=false;startX=event.clientX;startY=event.clientY;startLeft=viewport.scrollLeft;startTop=viewport.scrollTop;viewport.classList.add('dragging');viewport.setPointerCapture(event.pointerId)};viewport.onpointermove=event=>{if(!dragging)return;const dx=event.clientX-startX,dy=event.clientY-startY;if(Math.abs(dx)+Math.abs(dy)>4)moved=true;viewport.scrollLeft=startLeft-dx;viewport.scrollTop=startTop-dy};viewport.onpointerup=viewport.onpointercancel=event=>{if(!dragging)return;dragging=false;viewport.classList.remove('dragging');if(viewport.hasPointerCapture(event.pointerId))viewport.releasePointerCapture(event.pointerId)};viewport.onclick=event=>{if(moved){event.preventDefault();event.stopPropagation();moved=false}};viewport.onwheel=event=>{event.preventDefault();if(!canvas)return;const rect=viewport.getBoundingClientRect(),pointerX=event.clientX-rect.left,pointerY=event.clientY-rect.top,worldX=(viewport.scrollLeft+pointerX)/zoom,worldY=(viewport.scrollTop+pointerY)/zoom,next=clamp(zoom*(event.deltaY<0?1.12:.89),.32,1.65);if(next===zoom)return;zoom=next;canvas.style.zoom=zoom;viewport.scrollLeft=worldX*zoom-pointerX;viewport.scrollTop=worldY*zoom-pointerY;viewport.dataset.zoom=`${Math.round(zoom*100)}%`;viewport.setAttribute('aria-label',`Skill tree · ${viewport.dataset.zoom} zoom`)} }
function enableSkillTreePan(viewport){const canvas=viewport.querySelector('.skillTree'),pointers=new Map();let zoom=1,moved=false,panStart=null,pinchStart=null;viewport.title='Drag to move · Pinch or use the mouse wheel to zoom';const label=()=>{viewport.dataset.zoom=`${Math.round(zoom*100)}%`;viewport.setAttribute('aria-label',`Skill tree · ${viewport.dataset.zoom} zoom`)},zoomAt=(next,clientX,clientY)=>{if(!canvas)return;const rect=viewport.getBoundingClientRect(),x=clientX-rect.left,y=clientY-rect.top,worldX=(viewport.scrollLeft+x)/zoom,worldY=(viewport.scrollTop+y)/zoom;zoom=clamp(next,.32,1.65);canvas.style.zoom=zoom;viewport.scrollLeft=worldX*zoom-x;viewport.scrollTop=worldY*zoom-y;label()},distance=values=>Math.hypot(values[0].x-values[1].x,values[0].y-values[1].y),midpoint=values=>({x:(values[0].x+values[1].x)/2,y:(values[0].y+values[1].y)/2});viewport.onpointerdown=event=>{if(event.button!==0)return;if(event.pointerType==='mouse'&&event.target.closest('.skillNode'))return;pointers.set(event.pointerId,{x:event.clientX,y:event.clientY});viewport.setPointerCapture(event.pointerId);viewport.classList.add('dragging');if(pointers.size===1)panStart={x:event.clientX,y:event.clientY,left:viewport.scrollLeft,top:viewport.scrollTop};if(pointers.size===2){const values=[...pointers.values()],middle=midpoint(values),rect=viewport.getBoundingClientRect();pinchStart={distance:distance(values),zoom,worldX:(viewport.scrollLeft+middle.x-rect.left)/zoom,worldY:(viewport.scrollTop+middle.y-rect.top)/zoom};panStart=null}};viewport.onpointermove=event=>{if(!pointers.has(event.pointerId))return;pointers.set(event.pointerId,{x:event.clientX,y:event.clientY});if(pointers.size>=2&&pinchStart){const values=[...pointers.values()].slice(0,2),middle=midpoint(values),rect=viewport.getBoundingClientRect(),next=clamp(pinchStart.zoom*distance(values)/Math.max(1,pinchStart.distance),.32,1.65),x=middle.x-rect.left,y=middle.y-rect.top;zoom=next;canvas.style.zoom=zoom;viewport.scrollLeft=pinchStart.worldX*zoom-x;viewport.scrollTop=pinchStart.worldY*zoom-y;moved=true;label()}else if(pointers.size===1&&panStart){const point=[...pointers.values()][0],dx=point.x-panStart.x,dy=point.y-panStart.y;if(Math.abs(dx)+Math.abs(dy)>4)moved=true;viewport.scrollLeft=panStart.left-dx;viewport.scrollTop=panStart.top-dy}};const release=event=>{pointers.delete(event.pointerId);if(viewport.hasPointerCapture(event.pointerId))viewport.releasePointerCapture(event.pointerId);pinchStart=null;if(pointers.size===1){const point=[...pointers.values()][0];panStart={x:point.x,y:point.y,left:viewport.scrollLeft,top:viewport.scrollTop}}else{panStart=null;viewport.classList.remove('dragging')}};viewport.onpointerup=viewport.onpointercancel=release;viewport.onclick=event=>{if(moved){event.preventDefault();event.stopPropagation();moved=false}};viewport.onwheel=event=>{event.preventDefault();zoomAt(zoom*(event.deltaY<0?1.12:.89),event.clientX,event.clientY)}}
function useRunReroll(type){const r=state.run;if(!r?.rerolls?.[type])return;r.rerolls[type]--;if(type==='shop'){delete r.merchantStock;closeOverlay();merchantEvent()}else if(type==='vault'){closeOverlay();relicVault()}else if(type==='shrine'&&r.activeShrineHero){closeOverlay();chooseAbilityAugment(r.activeShrineHero)}save()}
function rerollRecruitment(){const r=state.run;if(!r?.rerolls?.recruit)return;r.rerolls.recruit--;r.recruitChoices=classRoster(currentPartyLevel());save();render()}
function openSettings(){showOverlay('Settings',`<div class="settingsPanel"><label class="masterMute"><input type="checkbox" ${masterMuted?'checked':''} onchange="setMasterMute(this.checked)"><span><b>Mute All Audio</b><small>Silence music and sound effects.</small></span></label><label class="volumeSetting"><span><b>Music Volume</b><output id="musicVolumeValue">${Math.round(musicVolume*100)}%</output></span><input type="range" min="0" max="1" step="0.05" value="${musicVolume}" oninput="setMusicVolume(this.value);document.querySelector('#musicVolumeValue').textContent=Math.round(this.value*100)+'%'"></label><label class="volumeSetting"><span><b>Sound Effects Volume</b><output id="sfxVolumeValue">${Math.round(sfxVolume*100)}%</output></span><input type="range" min="0" max="1" step="0.05" value="${sfxVolume}" oninput="setSfxVolume(this.value);document.querySelector('#sfxVolumeValue').textContent=Math.round(this.value*100)+'%'"></label><section class="settingsDanger"><h3>Reset Progress</h3><p>Permanently erase Gems, upgrades, trophies, history, unlocks, and the current expedition.</p><button class="btn danger" onclick="confirmResetProgress()">Reset All Progress</button></section></div><div class="actions"><button class="btn primary" onclick="closeOverlay()">Done</button></div>`)}
function confirmResetProgress(){showOverlay('⚠ Permanently Reset Everything?',`<div class="resetWarning"><strong>This cannot be undone.</strong><p>All permanent progression and the current run will be deleted. Audio settings will be kept.</p><p>Only continue if you are completely certain.</p></div><div class="actions"><button class="btn" onclick="openSettings()">Cancel</button><button class="btn danger resetConfirm" onclick="resetAllProgress()">Yes, Delete All Progress</button></div>`)}
function resetAllProgress(){state=fresh();save();closeOverlay();render();toast('All game progress has been reset.')}
function failedRunGems(r){if(!r||(!r.step&&!r.encounters&&!r.region))return 0;return Math.floor(((r.step||0)*1.5+(r.encounters||0)*2+(r.region||0)*20)*(r.endless?(r.gemMultiplier||1):1))}
function standardRunGems(won,r){const gems=won?40+r.encounters*3:failedRunGems(r);return gems}
function confirmAbandon(){const gems=failedRunGems(state.run);showOverlay('Abandon this expedition?',`<p>The party will disband and all unspent Run Gold will be lost.</p><p class="muted">Progress reward: ${gems} Gems.</p><div class="actions"><button class="btn" onclick="closeOverlay()">Continue Run</button><button class="btn danger" onclick="closeOverlay();endRun(false)">Abandon Expedition</button></div>`)}
