function enemyTurn(id){const e=turnUnit(id),b=state.run?.battle;if(!e||e.hp<=0||b?.activeUnitId!==id)return continueTurnBattle();const heroes=livingHeroes(),intent=enemyIntent(e);e.actionsTaken=(e.actionsTaken||0)+1;e.intent=null;playSfx(intent.kind==='aoe'?'lightning':'impact');if(intent.kind==='aoe'){let total=0;heroes.forEach(h=>total+=enemyDamage(e,h,enemyHasRole(e,'Boss')?.7:.6,'magical'));b.log.unshift(`${e.name} uses ${intent.label}, dealing ${total} magical damage across the party.`);return finishTurn(e)}const target=heroes.find(h=>h.id===intent.targetId)||heroes[0],gs=gearStats(target);if(e.damageType==='physical'&&Math.random()<gs.parry){b.log.unshift(`${target.name} parries ${e.name}.`);return finishTurn(e)}const execute=enemyHasRole(e,'Predator')&&target.hp/target.maxHp<.3?1.35:1,enrage=enemyHasRole(e,'Bruiser')&&e.hp/e.maxHp<.3?1.4:1,damage=enemyDamage(e,target,execute*enrage);if(target.guardTurns>0&&hasRelic('thornCrown')){const reflected=Math.max(1,Math.round(damage*.6));e.hp=Math.max(0,e.hp-reflected);recordDamageHit(e,reflected);b.log.unshift(`${target.name}'s Crown of Thorns reflects ${reflected} damage.`)}b.log.unshift(`${e.name} attacks ${target.name} for ${damage}${execute>1?' (Execute)':''}${enrage>1?' (Enraged)':''}.`);finishTurn(e)}
