  const b=state.run.battle,allies=livingHeroes(),enemies=livingEnemies(),ability=heroCombatAbilities(h).find(a=>a.key===action),gs=gearStats(h);
  if(action==='basic'){h.currentAction='basic';h.attackPulse=uid();playSfx(heroAttackSfx(h,action));const empowered=h.patientBladeReady,hits=turnDamage(h,target,1,heroWeaponDamageType(h));tryWeaponStatus(h,target);h.patientBladeReady=false;if(hasRelic('duelistCoin'))h.mana=Math.min(h.maxMana,h.mana+6);if(hits.crit&&skillBonus(h,'critMana'))h.mana=Math.min(h.maxMana,h.mana+skillBonus(h,'critMana'));b.log.unshift(`${h.name} attacks ${target.name} for ${hits.damage}${hits.superCrit?' super critical':hits.crit?' critical':''}${empowered?' with Patient Blade':''}.`);return finishTurn(h)}
