  const manaCost=payAbilityCost(h,ability);h.bloodHourActive=hasRelic('bloodHour');if(h.bloodHourActive){const sacrifice=Math.min(h.hp-1,Math.max(1,Math.round(h.maxHp*.05)));h.hp-=sacrifice;recordDamageHit(h,sacrifice)}let text='',refund=0;
