function queueSkillNode(heroId,nodeId){rememberSkillTreeView(heroId);const h=findHero(heroId),nodes=classSkillNodes(h?.class);if(!h)return;const pending=PENDING_SKILL_NODES[h.id]||(PENDING_SKILL_NODES[h.id]=[]),node=nodes.find(candidate=>candidate.id===nodeId);if(!node||skillRank(h,nodeId))return;const existing=pending.indexOf(nodeId);if(existing>=0){pending.splice(existing,1);let changed=true;while(changed){changed=false;for(let i=pending.length-1;i>=0;i--){const candidate=nodes.find(node=>node.id===pending[i]);if(!candidate||!plannedSkillNodeUnlocked(h,candidate,nodes,pending)){pending.splice(i,1);changed=true}}}}else if(pending.length<availableSkillPoints(h)&&plannedSkillNodeUnlocked(h,node,nodes,pending))pending.push(nodeId);openSkillTree(heroId)}
function confirmSkillPoints(heroId){rememberSkillTreeView(heroId);const h=findHero(heroId),pending=PENDING_SKILL_NODES[h?.id]||[];if(!h||!pending.length||pending.length>availableSkillPoints(h))return;recalculateAfterSkillChange(h,()=>{h.skillRanks=h.skillRanks||{};pending.forEach(id=>h.skillRanks[id]=1)});PENDING_SKILL_NODES[h.id]=[];save();openSkillTree(h.id)}
function respecSkillTree(heroId){rememberSkillTreeView(heroId);const h=findHero(heroId),cost=100*Math.pow(2,h?.skillRespecs||0);if(!h||!spentSkillPoints(h)||!state.run||state.run.gold<cost||!confirm(`Refund every allocated skill point for ${cost} gold?`))return;state.run.gold-=cost;recalculateAfterSkillChange(h,()=>{h.skillRanks={};h.skillRespecs=(h.skillRespecs||0)+1});PENDING_SKILL_NODES[h.id]=[];save();openSkillTree(h.id)}
function inspectHero(id){const h=findHero(id);if(!h)return;const race=RACE_DATA[h.race]||{},sub=chosenSubclass(h),passive=CLASS_PASSIVES[h.class],proc=weaponStatusProfile(h.gear?.Weapon);showOverlay(h.name,`<div class="characterInspect"><div class="characterIdentity">${img('classes/'+CLASSES[h.class].icon)}<div><h3>${h.name}</h3><div class="muted">${sub?.name||h.class} · ${h.race} · Level ${h.level} · <span class="rarity-${h.rarity}">${h.rarity}</span></div><div class="muted">${h.trait}</div></div><button class="btn characterSkillButton" onclick="closeOverlay();openSkillTree(${h.id})">Skill Tree · ${availableSkillPoints(h)} SP</button></div>${protectionStatSheet(h)}<section class="inspectSection"><h3>Weapon Effect</h3><p>${proc?`${Math.round(weaponProcChance(h)*100)}% chance to inflict ${proc.name}.`:'No weapon status effect.'}</p></section>${heroCombatAbilities(h).map(a=>`<section class="inspectSection abilityInspect"><h3>${a.name}</h3><p>${a.desc}</p><div class="itemStats"><span>${turnAbilityCost(h,a)} Mana</span></div></section>`).join('')}<section class="inspectSection"><h3>Class Passive · ${passive[0]}</h3><p>${passive[1]}</p></section><section class="inspectSection"><h3>Race Passive · ${race.passive||'Heritage'}</h3><p>${race.desc||'No racial modifier.'}</p></section>${sub?`<section class="inspectSection"><h3>Subclass · ${sub.name}</h3><p><b>Passive</b><br>${sub.passive}</p><p><b>Active</b><br>${sub.active}</p></section>`:''}${combatStatusDetails(h,false)}<section class="inspectSection"><h3>Equipment</h3><div class="inspectLoadout">${['Weapon','Armor','Accessory'].map(slot=>{const it=h.gear[slot];return `<button class="gearInspectCard" onclick="closeOverlay();inspectGear(${h.id},'${slot}')"><span>${slot}</span><strong>${it?.name||'Empty'}</strong><small>${it?itemStatLines(it).join(' · '):'Nothing equipped'}</small></button>`}).join('')}</div></section></div>`)}
async function init(){document.addEventListener?.('click',event=>{ensureMusic();if(event.target.closest?.('button:not(:disabled)'))playSfx('ui')});try{const [items,races,subclasses,recipes]=await Promise.all([fetch(ITEM_DATA_URL),fetch('../guildmaster/data/races.json'),fetch('../guildmaster/data/subclasses.json'),fetch('../guildmaster/data/recipes.json')]);if(!items.ok||!races.ok||!subclasses.ok||!recipes.ok)throw new Error('Shared Guildmaster data unavailable');[ITEM_DATA,RACE_DATA,SUBCLASS_DATA,RECIPE_DATA]=await Promise.all([items.json(),races.json(),subclasses.json(),recipes.json()]);normalizeDungeonRaces();Object.values(SUBCLASS_DATA).flat().forEach(sub=>{Object.assign(sub,SUBCLASS_TURN_OVERRIDES[sub.id]||{});sub.passive=subclassPassiveText(sub);sub.active=subclassActiveText(sub)})}catch(error){console.warn('Guildmaster shared data could not be loaded; fallback values will be used.',error)}await loadSkillTreeLayout();render()}
